INSERT IGNORE INTO t_note (id, user_id, title, cover, content, status, hot_score, like_count, collect_count, view_count, created_at) VALUES
(90000, 228, '打工人的第一支收纳盒，不后悔', 'https://picsum.photos/seed/n90000/640/400', '对比了三家最后选了这个，说说我手上这款云朵 收纳盒的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且皮肤敏感肌用着完全不闷痘。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 1415, 237, 3, 689, '2026-09-17 04:30:00'),
(90001, 230, '山海 手账本 Ultra两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90001/640/400', '通勤地铁上每天两小时，说说我手上这款山海 手账本 Ultra的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：但是戴久了耳道有点胀，超过三小时要摘下来歇歇。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1581, 134, 73, 814, '2026-09-15 15:48:00'),
(90002, 222, '预算36内怎么选？我选了它', 'https://picsum.photos/seed/n90002/640/400', '纠结了好久终于入手，说说我手上这款吱吱 蓝牙音箱 Pro的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 1192, 242, 40, 266, '2026-09-18 04:47:00'),
(90003, 202, '关于快充数据线，这篇讲全了', 'https://picsum.photos/seed/n90003/640/400', '入了半个月，几乎天天用，说说我手上这款白泽 快充数据线 Ultra的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且音质对得起这个价位，低音下潜够深。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 2305, 154, 21, 1738, '2026-08-27 18:11:00'),
(90004, 209, '打工人的第一支智能手表，不后悔', 'https://picsum.photos/seed/n90004/640/400', '朋友种草的，用了一周来还愿，说说我手上这款白泽 智能手表 Mini的真实感受。\n\n先说优点：做工细节在线，缝隙均匀没有廉价感；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：但是戴久了耳道有点胀，超过三小时要摘下来歇歇。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1882, 70, 70, 1322, '2026-09-08 08:20:00'),
(90005, 222, '被问爆了的真无线降噪耳机，来交作业了', 'https://picsum.photos/seed/n90005/640/400', '健身房常客亲测，说说我手上这款AirSound 真无线降噪耳机 Max的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 2243, 239, 2, 1516, '2026-09-12 20:09:00'),
(90006, 220, '关于运动腕表，这篇讲全了', 'https://picsum.photos/seed/n90006/640/400', '入了半个月，几乎天天用，说说我手上这款云朵 运动腕表 2代的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且皮肤敏感肌用着完全不闷痘。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1737, 178, 45, 978, '2026-09-19 21:10:00'),
(90007, 209, '预算301内怎么选？我选了它', 'https://picsum.photos/seed/n90007/640/400', '生日礼物自己挑的，说说我手上这款云朵 运动腕表 2代的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且皮肤敏感肌用着完全不闷痘。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 1990, 111, 70, 1307, '2026-08-31 01:08:00'),
(90008, 216, '预算1208内怎么选？我选了它', 'https://picsum.photos/seed/n90008/640/400', '生日礼物自己挑的，说说我手上这款AirSound 筋膜枪 青春版的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且做工细节在线，缝隙均匀没有廉价感。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 2639, 250, 9, 1844, '2026-09-06 14:02:00'),
(90009, 216, '关于手机壳，这篇讲全了', 'https://picsum.photos/seed/n90009/640/400', '纠结了好久终于入手，说说我手上这款半糖 手机壳 3代的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且颜值绝了，放桌面就是个摆件。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1981, 188, 49, 1172, '2026-09-19 08:04:00'),
(90010, 201, '被问爆了的手机壳，来交作业了', 'https://picsum.photos/seed/n90010/640/400', '搬进新家第一批购入，说说我手上这款半糖 手机壳 礼盒版的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且连接速度秒连，切换设备也很顺滑。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 1566, 22, 58, 1210, '2026-09-17 22:21:00'),
(90011, 209, '预算1236内怎么选？我选了它', 'https://picsum.photos/seed/n90011/640/400', '搬进新家第一批购入，说说我手上这款半糖 移动电源 Air的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 1466, 61, 63, 968, '2026-09-17 04:06:00'),
(90012, 202, '山海 宠物梳毛器 Ultra两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90012/640/400', '搬进新家第一批购入，说说我手上这款山海 宠物梳毛器 Ultra的真实感受。\n\n先说优点：做工细节在线，缝隙均匀没有廉价感；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 2324, 232, 2, 1618, '2026-09-06 06:53:00'),
(90013, 209, '打工人的第一支电竞耳机，不后悔', 'https://picsum.photos/seed/n90013/640/400', '搬进新家第一批购入，说说我手上这款闪充宝 电竞耳机 青春版的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且做工细节在线，缝隙均匀没有廉价感。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 969, 62, 34, 613, '2026-09-15 06:21:00'),
(90014, 212, '关于智能手表，这篇讲全了', 'https://picsum.photos/seed/n90014/640/400', '健身房常客亲测，说说我手上这款闪充宝 智能手表 Air的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且皮肤敏感肌用着完全不闷痘。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 1046, 296, 15, 83, '2026-09-05 10:08:00'),
(90015, 225, '吱吱 蓝牙音箱 Pro两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90015/640/400', '学生党预算有限认真做了功课，说说我手上这款吱吱 蓝牙音箱 Pro的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且颜值绝了，放桌面就是个摆件。\n\n也说说缺点：冬天金属外壳有点冰手。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 751, 41, 67, 293, '2026-09-05 06:34:00'),
(90016, 220, '被问爆了的狗狗玩具，来交作业了', 'https://picsum.photos/seed/n90016/640/400', '朋友种草的，用了一周来还愿，说说我手上这款吱吱 狗狗玩具 Ultra的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且做工细节在线，缝隙均匀没有廉价感。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 1235, 94, 48, 713, '2026-09-15 04:19:00'),
(90017, 222, '关于车载支架，这篇讲全了', 'https://picsum.photos/seed/n90017/640/400', '搬进新家第一批购入，说说我手上这款云朵 车载支架 Mini的真实感受。\n\n先说优点：音质对得起这个价位，低音下潜够深；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1149, 5, 54, 864, '2026-09-09 06:44:00'),
(90018, 226, '关于运动耳机，这篇讲全了', 'https://picsum.photos/seed/n90018/640/400', '打工人下班治愈好物，说说我手上这款吱吱 运动耳机 礼盒版的真实感受。\n\n先说优点：做工细节在线，缝隙均匀没有廉价感；而且防水名不虚传，出汗淋雨都没出过问题。\n\n也说说缺点：冬天金属外壳有点冰手。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 1403, 119, 15, 971, '2026-08-26 23:44:00'),
(90019, 228, '被问爆了的桌面加湿器，来交作业了', 'https://picsum.photos/seed/n90019/640/400', '朋友种草的，用了一周来还愿，说说我手上这款闪充宝 桌面加湿器的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 1691, 114, 48, 1109, '2026-09-05 06:28:00'),
