(90021, 202, 'AirSound 真无线降噪耳机 Max两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90021/640/400', '搬进新家第一批购入，说说我手上这款AirSound 真无线降噪耳机 Max的真实感受。\n\n先说优点：音质对得起这个价位，低音下潜够深；而且皮肤敏感肌用着完全不闷痘。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1687, 59, 75, 1135, '2026-09-12 04:12:00'),
(90022, 212, '预算44内怎么选？我选了它', 'https://picsum.photos/seed/n90022/640/400', '纠结了好久终于入手，说说我手上这款山海 真无线降噪耳机 Ultra的真实感受。\n\n先说优点：上手比想象中轻，戴一天耳朵也不累；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 752, 124, 37, 195, '2026-09-02 19:08:00'),
(90023, 209, '关于移动电源，这篇讲全了', 'https://picsum.photos/seed/n90023/640/400', '打工人下班治愈好物，说说我手上这款白泽 移动电源 Pro的真实感受。\n\n先说优点：做工细节在线，缝隙均匀没有廉价感；而且连接速度秒连，切换设备也很顺滑。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 42357, 2508, 1183, 28918, '2026-09-10 23:21:00'),
(90024, 212, '关于香水，这篇讲全了', 'https://picsum.photos/seed/n90024/640/400', '朋友种草的，用了一周来还愿，说说我手上这款闪充宝 香水 3代的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1659, 142, 18, 1143, '2026-09-12 20:54:00'),
