(90056, 213, '被问爆了的蓝牙音箱，来交作业了', 'https://picsum.photos/seed/n90056/640/400', '学生党预算有限认真做了功课，说说我手上这款吱吱 蓝牙音箱 Ultra的真实感受。\n\n先说优点：做工细节在线，缝隙均匀没有廉价感；而且连接速度秒连，切换设备也很顺滑。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1082, 25, 2, 997, '2026-09-14 09:44:00'),
(90057, 221, '被问爆了的蓝牙音箱，来交作业了', 'https://picsum.photos/seed/n90057/640/400', '朋友种草的，用了一周来还愿，说说我手上这款山海 蓝牙音箱 礼盒版的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且做工细节在线，缝隙均匀没有廉价感。\n\n也说说缺点：冬天金属外壳有点冰手。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 1331, 140, 70, 561, '2026-09-11 22:52:00'),
(90058, 224, '被问爆了的防晒霜，来交作业了', 'https://picsum.photos/seed/n90058/640/400', '打工人下班治愈好物，说说我手上这款半糖 防晒霜 Ultra的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且连接速度秒连，切换设备也很顺滑。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1248, 259, 38, 281, '2026-09-03 08:34:00'),
(90059, 215, '半糖 智能手环 Pro两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90059/640/400', '打工人下班治愈好物，说说我手上这款半糖 智能手环 Pro的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 416, 33, 6, 287, '2026-09-03 04:43:00'),
(90060, 224, '白泽 磁吸无线充 Ultra两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90060/640/400', '入了半个月，几乎天天用，说说我手上这款白泽 磁吸无线充 Ultra的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且续航是真的顶，一周一充完全没焦虑。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 1479, 12, 3, 1428, '2026-09-07 22:41:00'),
(90061, 209, '关于收纳盒，这篇讲全了', 'https://picsum.photos/seed/n90061/640/400', '生日礼物自己挑的，说说我手上这款悦物 收纳盒 礼盒版的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：但是戴久了耳道有点胀，超过三小时要摘下来歇歇。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 1161, 49, 77, 629, '2026-09-05 21:06:00'),
