(90088, 219, '关于阅读架，这篇讲全了', 'https://picsum.photos/seed/n90088/640/400', '对比了三家最后选了这个，说说我手上这款云朵 阅读架 Mini的真实感受。\n\n先说优点：上手比想象中轻，戴一天耳朵也不累；而且连接速度秒连，切换设备也很顺滑。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1337, 22, 11, 1216, '2026-09-11 13:40:00'),
(90089, 203, '预算202内怎么选？我选了它', 'https://picsum.photos/seed/n90089/640/400', '通勤地铁上每天两小时，说说我手上这款白泽 防晒霜 Ultra的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且音质对得起这个价位，低音下潜够深。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 1949, 18, 65, 1570, '2026-09-06 01:46:00'),
(90090, 211, '预算931内怎么选？我选了它', 'https://picsum.photos/seed/n90090/640/400', '生日礼物自己挑的，说说我手上这款白泽 氮化镓充电器 Pro的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 1969, 86, 46, 1481, '2026-08-29 01:17:00'),
(90091, 229, '吱吱 狗狗玩具 Ultra两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90091/640/400', '纠结了好久终于入手，说说我手上这款吱吱 狗狗玩具 Ultra的真实感受。\n\n先说优点：颜值绝了，放桌面就是个摆件；而且续航是真的顶，一周一充完全没焦虑。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 2658, 288, 65, 1469, '2026-09-11 09:15:00'),
