(90120, 228, '轻氧 运动腕表两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90120/640/400', '对比了三家最后选了这个，说说我手上这款轻氧 运动腕表的真实感受。\n\n先说优点：音质对得起这个价位，低音下潜够深；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：但是戴久了耳道有点胀，超过三小时要摘下来歇歇。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 2140, 28, 27, 1921, '2026-08-28 23:46:00'),
(90121, 212, '关于手机壳，这篇讲全了', 'https://picsum.photos/seed/n90121/640/400', '生日礼物自己挑的，说说我手上这款半糖 手机壳 Mini的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且音质对得起这个价位，低音下潜够深。\n\n也说说缺点：冬天金属外壳有点冰手。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1560, 285, 54, 435, '2026-09-13 13:27:00'),
(90122, 227, '打工人的第一支狗狗玩具，不后悔', 'https://picsum.photos/seed/n90122/640/400', '打工人下班治愈好物，说说我手上这款闪充宝 狗狗玩具 Mini的真实感受。\n\n先说优点：音质对得起这个价位，低音下潜够深；而且连接速度秒连，切换设备也很顺滑。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 735, 65, 69, 195, '2026-09-18 11:43:00'),
(90123, 201, '预算157内怎么选？我选了它', 'https://picsum.photos/seed/n90123/640/400', '打工人下班治愈好物，说说我手上这款云朵 桌面收纳架 Ultra的真实感受。\n\n先说优点：做工细节在线，缝隙均匀没有廉价感；而且音质对得起这个价位，低音下潜够深。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 1318, 118, 5, 939, '2026-09-14 03:34:00'),
