(90153, 222, '白泽 智能手表 Mini两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90153/640/400', '搬进新家第一批购入，说说我手上这款白泽 智能手表 Mini的真实感受。\n\n先说优点：上手比想象中轻，戴一天耳朵也不累；而且皮肤敏感肌用着完全不闷痘。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 36623, 1819, 783, 27251, '2026-09-14 12:59:00'),
(90154, 221, '关于电竞耳机，这篇讲全了', 'https://picsum.photos/seed/n90154/640/400', '对比了三家最后选了这个，说说我手上这款闪充宝 电竞耳机 青春版的真实感受。\n\n先说优点：颜值绝了，放桌面就是个摆件；而且做工细节在线，缝隙均匀没有廉价感。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 27566, 1736, 947, 17623, '2026-09-11 08:07:00'),
(90155, 214, '半糖 手机壳 Mini两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90155/640/400', '朋友种草的，用了一周来还愿，说说我手上这款半糖 手机壳 Mini的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 1751, 182, 24, 1085, '2026-09-12 18:21:00'),
(90156, 202, '打工人的第一支智能手表，不后悔', 'https://picsum.photos/seed/n90156/640/400', '搬进新家第一批购入，说说我手上这款山海 智能手表 Max的真实感受。\n\n先说优点：颜值绝了，放桌面就是个摆件；而且皮肤敏感肌用着完全不闷痘。\n\n也说说缺点：冬天金属外壳有点冰手。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 168, 4, 5, 131, '2026-09-18 14:34:00'),
