(90185, 215, '关于氛围灯，这篇讲全了', 'https://picsum.photos/seed/n90185/640/400', '生日礼物自己挑的，说说我手上这款轻氧 氛围灯 Pro的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且皮肤敏感肌用着完全不闷痘。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1852, 127, 7, 1436, '2026-09-08 10:58:00'),
(90186, 208, '预算1235内怎么选？我选了它', 'https://picsum.photos/seed/n90186/640/400', '入了半个月，几乎天天用，说说我手上这款白泽 中性笔套装 Air的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：冬天金属外壳有点冰手。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1220, 220, 26, 430, '2026-09-02 11:30:00'),
(90187, 214, '关于电竞耳机，这篇讲全了', 'https://picsum.photos/seed/n90187/640/400', '生日礼物自己挑的，说说我手上这款闪充宝 电竞耳机 青春版的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且颜值绝了，放桌面就是个摆件。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 2766, 233, 54, 1797, '2026-09-10 21:08:00'),
(90188, 221, '关于蓝牙音箱，这篇讲全了', 'https://picsum.photos/seed/n90188/640/400', '对比了三家最后选了这个，说说我手上这款吱吱 蓝牙音箱 Pro的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且连接速度秒连，切换设备也很顺滑。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 2154, 218, 28, 1360, '2026-09-04 15:59:00'),
(90189, 225, '预算62内怎么选？我选了它', 'https://picsum.photos/seed/n90189/640/400', '通勤地铁上每天两小时，说说我手上这款山海 保湿唇釉的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1858, 85, 42, 1393, '2026-09-07 07:49:00'),
(90190, 226, '被问爆了的智能手表，来交作业了', 'https://picsum.photos/seed/n90190/640/400', '学生党预算有限认真做了功课，说说我手上这款山海 智能手表 Max的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且音质对得起这个价位，低音下潜够深。\n\n也说说缺点：但是戴久了耳道有点胀，超过三小时要摘下来歇歇。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 547, 47, 12, 346, '2026-09-14 13:48:00'),
