(90218, 213, '预算221内怎么选？我选了它', 'https://picsum.photos/seed/n90218/640/400', '对比了三家最后选了这个，说说我手上这款吱吱 骑行手套 3代的真实感受。\n\n先说优点：上手比想象中轻，戴一天耳朵也不累；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：冬天金属外壳有点冰手。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 35414, 1091, 960, 27341, '2026-09-08 03:24:00'),
(90219, 225, '原野 卸妆膏 Ultra两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90219/640/400', '生日礼物自己挑的，说说我手上这款原野 卸妆膏 Ultra的真实感受。\n\n先说优点：做工细节在线，缝隙均匀没有廉价感；而且续航是真的顶，一周一充完全没焦虑。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 2379, 115, 60, 1734, '2026-09-07 12:44:00'),
(90220, 219, '关于头戴式耳机，这篇讲全了', 'https://picsum.photos/seed/n90220/640/400', '入了半个月，几乎天天用，说说我手上这款云朵 头戴式耳机 Max的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：但是戴久了耳道有点胀，超过三小时要摘下来歇歇。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1024, 30, 9, 889, '2026-09-17 01:21:00'),
(90221, 230, '关于氛围灯，这篇讲全了', 'https://picsum.photos/seed/n90221/640/400', '入了半个月，几乎天天用，说说我手上这款山海 氛围灯 Air的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且颜值绝了，放桌面就是个摆件。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 1965, 162, 58, 1189, '2026-09-11 22:23:00'),
