(90250, 208, '被问爆了的保湿唇釉，来交作业了', 'https://picsum.photos/seed/n90250/640/400', '健身房常客亲测，说说我手上这款AirSound 保湿唇釉 Pro的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且音质对得起这个价位，低音下潜够深。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 1830, 18, 73, 1411, '2026-08-29 14:08:00'),
(90251, 217, '被问爆了的保湿唇釉，来交作业了', 'https://picsum.photos/seed/n90251/640/400', '入了半个月，几乎天天用，说说我手上这款山海 保湿唇釉的真实感受。\n\n先说优点：音质对得起这个价位，低音下潜够深；而且颜值绝了，放桌面就是个摆件。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 633, 142, 22, 97, '2026-09-11 22:17:00'),
(90252, 202, '预算816内怎么选？我选了它', 'https://picsum.photos/seed/n90252/640/400', '打工人下班治愈好物，说说我手上这款白泽 磁吸无线充 Ultra的真实感受。\n\n先说优点：音质对得起这个价位，低音下潜够深；而且连接速度秒连，切换设备也很顺滑。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1557, 249, 31, 655, '2026-09-16 10:12:00'),
