(90254, 229, '被问爆了的香薰机，来交作业了', 'https://picsum.photos/seed/n90254/640/400', '对比了三家最后选了这个，说说我手上这款闪充宝 香薰机 Max的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 2063, 82, 46, 1587, '2026-09-10 20:27:00'),
(90255, 202, '被问爆了的氮化镓充电器，来交作业了', 'https://picsum.photos/seed/n90255/640/400', '入了半个月，几乎天天用，说说我手上这款山海 氮化镓充电器的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：但是戴久了耳道有点胀，超过三小时要摘下来歇歇。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 28888, 1708, 483, 21349, '2026-09-05 13:03:00'),
