(90283, 217, '打工人的第一支气垫粉底，不后悔', 'https://picsum.photos/seed/n90283/640/400', '生日礼物自己挑的，说说我手上这款原野 气垫粉底 Air的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 723, 133, 13, 259, '2026-09-13 08:58:00'),
