(90315, 206, '被问爆了的运动腕表，来交作业了', 'https://picsum.photos/seed/n90315/640/400', '打工人下班治愈好物，说说我手上这款云朵 运动腕表 2代的真实感受。\n\n先说优点：颜值绝了，放桌面就是个摆件；而且连接速度秒连，切换设备也很顺滑。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 1935, 115, 38, 1400, '2026-09-16 15:29:00'),
(90316, 221, '打工人的第一支跳绳，不后悔', 'https://picsum.photos/seed/n90316/640/400', '入了半个月，几乎天天用，说说我手上这款吱吱 跳绳 礼盒版的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且颜值绝了，放桌面就是个摆件。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1522, 42, 27, 1261, '2026-09-14 21:35:00'),
(90317, 222, '关于智能手表，这篇讲全了', 'https://picsum.photos/seed/n90317/640/400', '打工人下班治愈好物，说说我手上这款悦物 智能手表 3代的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且连接速度秒连，切换设备也很顺滑。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1510, 196, 47, 687, '2026-09-12 18:39:00'),
(90318, 217, '关于智能手环，这篇讲全了', 'https://picsum.photos/seed/n90318/640/400', '通勤地铁上每天两小时，说说我手上这款云朵 智能手环 Air的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且连接速度秒连，切换设备也很顺滑。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 1052, 19, 7, 960, '2026-08-28 01:13:00'),
(90319, 208, '预算1176内怎么选？我选了它', 'https://picsum.photos/seed/n90319/640/400', '学生党预算有限认真做了功课，说说我手上这款山海 氛围灯 Air的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 2053, 49, 71, 1551, '2026-09-17 09:58:00'),
