(90348, 209, '关于磁吸无线充，这篇讲全了', 'https://picsum.photos/seed/n90348/640/400', '纠结了好久终于入手，说说我手上这款云朵 磁吸无线充 青春版的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且续航是真的顶，一周一充完全没焦虑。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1271, 74, 59, 754, '2026-09-09 05:54:00'),
(90349, 216, '打工人的第一支宠物梳毛器，不后悔', 'https://picsum.photos/seed/n90349/640/400', '通勤地铁上每天两小时，说说我手上这款山海 宠物梳毛器 Ultra的真实感受。\n\n先说优点：上手比想象中轻，戴一天耳朵也不累；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 1856, 284, 7, 969, '2026-09-17 14:22:00'),
