(90381, 211, '预算1191内怎么选？我选了它', 'https://picsum.photos/seed/n90381/640/400', '入了半个月，几乎天天用，说说我手上这款AirSound 快充数据线 礼盒版的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 1888, 116, 67, 1205, '2026-08-25 04:58:00'),
(90382, 226, '关于中性笔套装，这篇讲全了', 'https://picsum.photos/seed/n90382/640/400', '通勤地铁上每天两小时，说说我手上这款悦物 中性笔套装 Air的真实感受。\n\n先说优点：上手比想象中轻，戴一天耳朵也不累；而且做工细节在线，缝隙均匀没有廉价感。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 2908, 243, 78, 1789, '2026-09-16 04:02:00'),
(90383, 216, '关于电竞耳机，这篇讲全了', 'https://picsum.photos/seed/n90383/640/400', '纠结了好久终于入手，说说我手上这款山海 电竞耳机 Air的真实感受。\n\n先说优点：上手比想象中轻，戴一天耳朵也不累；而且续航是真的顶，一周一充完全没焦虑。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 2127, 294, 52, 985, '2026-09-17 03:41:00'),
(90384, 201, '被问爆了的气垫粉底，来交作业了', 'https://picsum.photos/seed/n90384/640/400', '入了半个月，几乎天天用，说说我手上这款原野 气垫粉底 Air的真实感受。\n\n先说优点：降噪一开世界都安静了，地铁轰鸣声直接消失；而且连接速度秒连，切换设备也很顺滑。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 2397, 144, 10, 1915, '2026-08-31 11:30:00'),
(90385, 230, '轻氧 保湿唇釉 Ultra两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90385/640/400', '入了半个月，几乎天天用，说说我手上这款轻氧 保湿唇釉 Ultra的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且皮肤敏感肌用着完全不闷痘。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 451, 57, 35, 105, '2026-09-13 08:44:00'),
(90386, 215, '打工人的第一支氮化镓充电器，不后悔', 'https://picsum.photos/seed/n90386/640/400', '健身房常客亲测，说说我手上这款山海 氮化镓充电器的真实感受。\n\n先说优点：做工细节在线，缝隙均匀没有廉价感；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 35586, 1118, 842, 28022, '2026-09-09 05:52:00'),
(90387, 226, '悦物 智能手表 3代两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90387/640/400', '对比了三家最后选了这个，说说我手上这款悦物 智能手表 3代的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且颜值绝了，放桌面就是个摆件。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 1311, 69, 55, 829, '2026-08-28 13:05:00'),
