(90413, 209, '关于头戴式耳机，这篇讲全了', 'https://picsum.photos/seed/n90413/640/400', '学生党预算有限认真做了功课，说说我手上这款云朵 头戴式耳机 Max的真实感受。\n\n先说优点：上手比想象中轻，戴一天耳朵也不累；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1672, 221, 17, 924, '2026-09-06 13:02:00'),
