(90444, 223, '关于儿童电话手表，这篇讲全了', 'https://picsum.photos/seed/n90444/640/400', '健身房常客亲测，说说我手上这款云朵 儿童电话手表 青春版的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且做工细节在线，缝隙均匀没有廉价感。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 2280, 298, 21, 1281, '2026-09-18 07:27:00'),
(90445, 228, '云朵 阅读架 Mini两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90445/640/400', '入了半个月，几乎天天用，说说我手上这款云朵 阅读架 Mini的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且续航是真的顶，一周一充完全没焦虑。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 744, 19, 14, 617, '2026-09-11 23:33:00'),
