(90476, 212, '打工人的第一支宠物饮水机，不后悔', 'https://picsum.photos/seed/n90476/640/400', '对比了三家最后选了这个，说说我手上这款半糖 宠物饮水机 Max的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且皮肤敏感肌用着完全不闷痘。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 2468, 112, 27, 1997, '2026-08-27 05:12:00'),
(90477, 215, '被问爆了的运动水壶，来交作业了', 'https://picsum.photos/seed/n90477/640/400', '健身房常客亲测，说说我手上这款吱吱 运动水壶 Ultra的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1060, 296, 1, 167, '2026-09-04 12:29:00'),
(90478, 204, '悦物 筋膜枪 礼盒版两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90478/640/400', '对比了三家最后选了这个，说说我手上这款悦物 筋膜枪 礼盒版的真实感受。\n\n先说优点：续航是真的顶，一周一充完全没焦虑；而且音质对得起这个价位，低音下潜够深。\n\n也说说缺点：颜色比图片稍深一点，介意的注意下。\n\n蹲一个活动的姐妹可以冲，早买早享受。', 'PUBLISHED', 1648, 135, 12, 1183, '2026-09-11 13:53:00'),
(90479, 202, '预算352内怎么选？我选了它', 'https://picsum.photos/seed/n90479/640/400', '健身房常客亲测，说说我手上这款山海 阅读架 Air的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且音质对得起这个价位，低音下潜够深。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 1516, 173, 15, 922, '2026-08-31 22:21:00'),
(90480, 206, '打工人的第一支猫爬架，不后悔', 'https://picsum.photos/seed/n90480/640/400', '健身房常客亲测，说说我手上这款悦物 猫爬架 Ultra的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且续航是真的顶，一周一充完全没焦虑。\n\n也说说缺点：包装过于朴素，送人得自己再包一下。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1657, 37, 66, 1216, '2026-08-26 13:41:00'),
(90481, 209, '预算757内怎么选？我选了它', 'https://picsum.photos/seed/n90481/640/400', '通勤地铁上每天两小时，说说我手上这款山海 氮化镓充电器的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且续航是真的顶，一周一充完全没焦虑。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1789, 108, 56, 1185, '2026-09-06 17:19:00'),
(90482, 228, '打工人的第一支磁吸无线充，不后悔', 'https://picsum.photos/seed/n90482/640/400', '健身房常客亲测，说说我手上这款白泽 磁吸无线充 Ultra的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且上手比想象中轻，戴一天耳朵也不累。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1554, 9, 28, 1387, '2026-09-09 02:37:00'),
(90483, 226, '关于筋膜枪，这篇讲全了', 'https://picsum.photos/seed/n90483/640/400', '健身房常客亲测，说说我手上这款悦物 筋膜枪 礼盒版的真实感受。\n\n先说优点：皮肤敏感肌用着完全不闷痘；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n也说说缺点：冬天金属外壳有点冰手。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1712, 76, 39, 1289, '2026-09-04 02:29:00'),
(90484, 203, '被问爆了的真无线降噪耳机，来交作业了', 'https://picsum.photos/seed/n90484/640/400', '对比了三家最后选了这个，说说我手上这款AirSound 真无线降噪耳机 Max的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：但是戴久了耳道有点胀，超过三小时要摘下来歇歇。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 957, 267, 6, 126, '2026-09-14 06:57:00'),
(90485, 229, '预算706内怎么选？我选了它', 'https://picsum.photos/seed/n90485/640/400', '搬进新家第一批购入，说说我手上这款半糖 宠物饮水机 Mini的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且音质对得起这个价位，低音下潜够深。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1533, 32, 20, 1337, '2026-08-30 23:38:00'),
(90486, 224, '被问爆了的儿童电话手表，来交作业了', 'https://picsum.photos/seed/n90486/640/400', '纠结了好久终于入手，说说我手上这款闪充宝 儿童电话手表 礼盒版的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且上手比想象中轻，戴一天耳朵也不累。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1916, 240, 28, 1056, '2026-09-13 20:30:00'),
(90487, 214, '关于收纳盒，这篇讲全了', 'https://picsum.photos/seed/n90487/640/400', '搬进新家第一批购入，说说我手上这款悦物 收纳盒 礼盒版的真实感受。\n\n先说优点：充电速度肉眼可见地快，洗个澡的功夫就满电；而且做工细节在线，缝隙均匀没有廉价感。\n\n也说说缺点：app 偶尔断连，重启就好，不算大毛病。\n\n总体这个价位很难找到对手，推荐给同需求的朋友～', 'PUBLISHED', 2126, 258, 65, 1027, '2026-09-14 15:05:00'),
(90488, 207, '关于保温杯，这篇讲全了', 'https://picsum.photos/seed/n90488/640/400', '生日礼物自己挑的，说说我手上这款AirSound 保温杯 2代的真实感受。\n\n先说优点：颜值绝了，放桌面就是个摆件；而且防水名不虚传，出汗淋雨都没出过问题。\n\n个人体验供参考，适合自己的才是最好的。', 'PUBLISHED', 1635, 279, 44, 578, '2026-09-14 19:41:00'),
(90489, 220, '打工人的第一支桌面收纳架，不后悔', 'https://picsum.photos/seed/n90489/640/400', '打工人下班治愈好物，说说我手上这款云朵 桌面收纳架 Ultra的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且充电速度肉眼可见地快，洗个澡的功夫就满电。\n\n后续用久了再来追评，目前是满意的。', 'PUBLISHED', 1643, 257, 72, 512, '2026-09-13 03:00:00'),
(90490, 209, 'AirSound 蓝牙音箱 Air两周真实体验，优缺点全说', 'https://picsum.photos/seed/n90490/640/400', '学生党预算有限认真做了功课，说说我手上这款AirSound 蓝牙音箱 Air的真实感受。\n\n先说优点：连接速度秒连，切换设备也很顺滑；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n也说说缺点：没有附送收纳袋，出门只能裸塞包里。\n\n不算完美但值回票价，理性种草！', 'PUBLISHED', 1550, 109, 9, 1178, '2026-09-06 20:51:00'),
(90491, 202, '被问爆了的阅读架，来交作业了', 'https://picsum.photos/seed/n90491/640/400', '朋友种草的，用了一周来还愿，说说我手上这款云朵 阅读架 Mini的真实感受。\n\n先说优点：防水名不虚传，出汗淋雨都没出过问题；而且降噪一开世界都安静了，地铁轰鸣声直接消失。\n\n已经安利给两个同事了，都说真香。', 'PUBLISHED', 1067, 46, 68, 589, '2026-09-03 01:45:00'),
